experience_css:
/* Research Experience: compact full-width rows */
  .exp-list {
    display: flex;
    flex-direction: column;
  }
  .exp-item {
    display: grid;
    grid-template-columns: 240px minmax(0, 1fr) auto;
    column-gap: 28px;
    align-items: center;
    padding: 16px 0;
    border: none;
    border-bottom: 1px solid var(--line-soft);
    background: transparent;
  }
  .exp-item:last-child { border-bottom: none; }
  .exp-logo-box {
    width: 240px; height: 80px;
    display: flex; align-items: center; justify-content: center;
    border: none; border-radius: 0; background: none; box-shadow: none; overflow: visible;
  }
  .exp-logo-box img {
    width: auto; max-width: 220px; max-height: 68px; height: auto;
    object-fit: contain; object-position: center; display: block;
  }
  .exp-main {
    display: flex;
    flex-direction: column;
    gap: 3px;
    min-width: 0;
  }
  .exp-side {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 4px;
    justify-self: end;
    text-align: right;
  }
  .exp-period {
    font-size: 12.5px; font-weight: 500;
    letter-spacing: .04em;
    color: var(--ink-faint); margin: 0;
    white-space: nowrap;
  }
  .exp-place {
    margin: 0;
    font-size: 12.5px; color: var(--ink-faint); line-height: 1.4;
    white-space: nowrap;
  }
  .exp-list .org { font-size: 17px; }
  .exp-list .org a { color: var(--accent); }
  .exp-list .org a:hover { text-decoration: underline; }
  .exp-list .role { font-size: 13.5px; margin-top: 0; }
